<?= $this->extend('layouts/main') ?>
<?= $this->section('content') ?>
<section class="panel">
    <div class="section-heading"><div><p class="eyebrow">Team access</p><h2><?= count($staff) ?> staff accounts</h2></div><a class="button primary" href="<?= site_url('staff/new') ?>"><i data-lucide="user-plus"></i><span>Add staff</span></a></div>
