    <?php foreach ($staff as $member): ?><tr class="<?= $member['is_active'] ? '' : 'muted-row' ?>"><td><div class="entity"><div class="avatar table-avatar"><?php if ($member['avatar']): ?><img src="<?= base_url(esc($member['avatar'])) ?>" alt=""><?php else: ?><?= esc(strtoupper(substr($member['full_name'], 0, 1))) ?><?php endif ?></div><strong><?= esc($member['full_name']) ?><?= (int) $member['id'] === (int) session('user_id') ? ' (You)' : '' ?></strong></div></td><td>@<?= esc($member['username']) ?></td><td><span class="badge <?= $member['is_active'] ? 'active' : 'archived' ?>"><?= $member['is_active'] ? 'Active' : 'Archived' ?></span></td><td><?= date('M j, Y', strtotime($member['created_at'])) ?></td><td class="actions"><a class="icon-button" href="<?= site_url('staff/' . $member['id'] . '/edit') ?>" title="Edit staff member" aria-label="Edit <?= esc($member['full_name']) ?>"><i data-lucide="pencil"></i></a><?php if ((int) $member['id'] !== (int) session('user_id')): ?><form method="post" action="<?= site_url('staff/' . $member['id'] . '/archive') ?>"><?= csrf_field() ?><button class="icon-button" type="submit" title="<?= $member['is_active'] ? 'Archive' : 'Restore' ?> account" aria-label="<?= $member['is_active'] ? 'Archive' : 'Restore' ?> <?= esc($member['full_name']) ?>"><i data-lucide="<?= $member['is_active'] ? 'user-x' : 'user-check' ?>"></i></button></form><?php endif ?></td></tr><?php endforeach ?>
    </tbody></table></div>
</section>
